<?php require 'config.php'; need(['nurse','doctor']); check();$msg=$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  if(isset($_POST['pname'])&&user()['role']=='doctor'){try{$pdo->prepare('INSERT INTO procedures_catalog(name,price) VALUES(?,?)')->execute([trim($_POST['pname']),max(0,(float)$_POST['price'])]);$msg='Procedure added.';}catch(PDOException $x){$err='That procedure already exists.';}}
  else{$o=$pdo->prepare("SELECT * FROM procedure_orders WHERE id=? AND status='queued'");$o->execute([(int)($_POST['order']??0)]);$o=$o->fetch();
    if($o&&isset($_POST['cancel'])){$pdo->prepare("UPDATE procedure_orders SET status='cancelled' WHERE id=?")->execute([$o['id']]);advance($o['visit_id'],'consultation');audit('procedure cancelled '.$o['id']);$msg='Order cancelled.';}
    elseif($o){if(trim($_POST['outcome'])===''||!isset($_POST['consent']))$err='Write the outcome and confirm that consent was obtained.';
      else{$pdo->prepare("UPDATE procedure_orders SET status='done',outcome=?,complications=?,consent=1,performed_by=?,done_at=NOW() WHERE id=?")->execute([trim($_POST['outcome']),trim($_POST['comp']),user()['id'],$o['id']]);advance($o['visit_id'],'consultation');audit('procedure done '.$o['id']);header('Location: slip.php?kind=procedure&visit='.$o['visit_id'].'&back=procedures.php');exit;}}}}
head('Procedures');if($msg)echo '<p class=ok>'.e($msg).'</p>';if($err)echo '<p class=err>'.e($err).'</p>';
$rows=$pdo->query("SELECT o.*,c.name pn,p.patient_no,p.first_name,p.last_name,u.name doc FROM procedure_orders o JOIN procedures_catalog c ON c.id=o.proc_id JOIN visits v ON v.id=o.visit_id JOIN patients p ON p.id=v.patient_id LEFT JOIN users u ON u.id=o.ordered_by WHERE o.status='queued' ORDER BY o.id")->fetchAll();
echo '<h3>Waiting for a procedure</h3>';if(!$rows)echo '<div class=card><p>No procedures waiting. Doctors order them on the consultation page.</p></div>';
foreach($rows as $o)echo '<div class=card><b>'.e($o['pn']).'</b> for '.e($o['patient_no'].' '.$o['first_name'].' '.$o['last_name']).'<br><small>Ordered by '.e($o['doc']).' | Indication: '.e($o['indication']).'</small><form method=post>'.field().'<input type=hidden name=order value='.$o['id'].'><label>Outcome</label><textarea name=outcome></textarea><label>Complications (if any)</label><input name=comp><label style="font-weight:400"><input type=checkbox name=consent style="width:auto"> Patient or guardian gave consent</label><button>Save outcome and print</button> <button name=cancel value=1 style="background:#a23b2a" onclick="return confirm(\'Cancel this order?\')">Cancel order</button></form></div>';?>
<div class=card><h3>Recent procedures</h3><table><tr><th>Patient<th>Procedure<th>Outcome<th>Done<th></tr>
<?php foreach($pdo->query("SELECT o.visit_id,o.outcome,o.done_at,c.name,p.patient_no,p.first_name,p.last_name FROM procedure_orders o JOIN procedures_catalog c ON c.id=o.proc_id JOIN visits v ON v.id=o.visit_id JOIN patients p ON p.id=v.patient_id WHERE o.status='done' ORDER BY o.id DESC LIMIT 30") as $o)echo '<tr><td>'.e($o['patient_no'].' '.$o['first_name'].' '.$o['last_name']).'<td>'.e($o['name']).'<td>'.e($o['outcome']).'<td>'.substr($o['done_at'],0,16).'<td><a target=_blank href="slip.php?kind=procedure&visit='.$o['visit_id'].'&back=procedures.php">Print</a>';?></table></div>
<?php if(user()['role']=='doctor'||user()['role']=='admin'):?><div class=card><h3>Add a procedure to the catalogue</h3><form method=post class=g><?=field()?><div><input name=pname placeholder="Procedure name" required></div><div><input name=price type=number step=0.01 min=0 placeholder="Price (KES)"></div><div><button style="margin:0">Add</button></div></form></div><?php endif;foot();
